H.background();
const w = H.W, h = H.H;
const Vp = Math.max(1, P.Vp);         // primary rms voltage, volts
const Np = Math.max(1, Math.round(P.Np)); // primary turns
const Ns = Math.max(1, Math.round(P.Ns)); // secondary turns
const ratio = Ns / Np;
const Vs = Vp * ratio;                // ideal transformer: Vs = Vp * Ns/Np
// AC waveforms (instantaneous), peak = rms*sqrt(2), oscillate with t -> looping
const f = 0.6;
const vp_inst = Vp * Math.SQRT2 * Math.sin(t * f * H.TAU / 1.0 * 0.5 + 0);
const vs_inst = Vs * Math.SQRT2 * Math.sin(t * f * H.TAU / 1.0 * 0.5 + 0);
// Core (two vertical bars + top/bottom yokes)
const coreL = w * 0.40, coreR = w * 0.60, coreT = h * 0.30, coreB = h * 0.78;
H.rect(coreL - 10, coreT - 10, 20, coreB - coreT + 20, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
H.rect(coreR - 10, coreT - 10, 20, coreB - coreT + 20, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
H.rect(coreL - 10, coreT - 10, coreR - coreL + 20, 18, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
H.rect(coreL - 10, coreB - 8, coreR - coreL + 20, 18, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
// oscillating flux brightness in core (Faraday: same Φ links both coils)
const fluxGlow = Math.abs(Math.sin(t * f * H.TAU * 0.5));
H.text("Φ", (coreL + coreR) / 2 - 6, coreT + 6, { color: H.hsl(45, 90, 40 + 40 * fluxGlow), size: 16, weight: 700 });
// windings — loop COUNTS reflect the turns ratio (larger side capped at 14)
const Nmax = Math.max(Np, Ns);
const drawCap = 14;
const npDraw = Math.max(1, Math.round(Np / Nmax * drawCap));
const nsDraw = Math.max(1, Math.round(Ns / Nmax * drawCap));
for (let i = 0; i < npDraw; i++) {
  const yy = coreT + 14 + i * (coreB - coreT - 28) / Math.max(1, npDraw);
  H.circle(coreL - 10, yy, 9, { stroke: H.colors.accent, width: 2.5 });
}
for (let i = 0; i < nsDraw; i++) {
  const yy = coreT + 14 + i * (coreB - coreT - 28) / Math.max(1, nsDraw);
  H.circle(coreR + 10, yy, 9, { stroke: H.colors.accent2, width: 2.5 });
}
// AC source on primary, lamp/load on secondary
const sx = w * 0.16, lx = w * 0.84, midY = (coreT + coreB) / 2;
H.circle(sx, midY, 22, { stroke: H.colors.accent, width: 3 });
H.text("~", sx - 5, midY + 7, { color: H.colors.accent, size: 22, weight: 700 });
H.arrow(sx + 22, midY - vp_inst / (Vp * Math.SQRT2) * 28, coreL - 24, midY - vp_inst / (Vp * Math.SQRT2) * 28, { color: H.colors.accent, width: 2, head: 7 });
H.circle(lx, midY, 16, { stroke: H.colors.accent2, width: 3 });
H.text("Vp", sx - 12, midY + 44, { color: H.colors.accent, size: 13 });
H.text("Vs", lx - 12, midY + 44, { color: H.colors.accent2, size: 13 });
// little bar gauges for instantaneous voltage — shared px/volt scale so the
// taller side (Vp or Vs) fills ~70px and the amplitude RATIO stays visible
const vMaxPeak = Math.max(Vp, Vs) * Math.SQRT2;
const gscale = 70 / vMaxPeak;
H.line(sx - 20, midY + 56, sx - 20 + vp_inst * gscale, midY + 56, { color: H.colors.accent, width: 5 });
H.line(lx - 20, midY + 56, lx - 20 + vs_inst * gscale, midY + 56, { color: H.colors.accent2, width: 5 });
const kind = ratio > 1 ? "step-up" : ratio < 1 ? "step-down" : "isolation (1:1)";
H.text("Transformer:  Vs / Vp = Ns / Np", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Np = " + Np + "   Ns = " + Ns + "   ratio Ns/Np = " + ratio.toFixed(2) + "   (" + kind + ")", 24, 52, { color: H.colors.sub, size: 13 });
H.text("Vp = " + Vp.toFixed(1) + " V  →  Vs = " + Vs.toFixed(1) + " V    (v_s now = " + vs_inst.toFixed(1) + " V)", 24, h - 22, { color: H.colors.good, size: 14 });
H.legend([{ label: "primary", color: H.colors.accent }, { label: "secondary", color: H.colors.accent2 }], w - 170, 28);
